const t = $('ENTRADA (Execute Workflow Trigger)').first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.motor.ejecutar_motor() (Python, unica autoridad: invoca
// pipeline_tiquipaya.procesar_cierre_completo() de V2 sin cambios). Este
// nodo NUNCA decide nada de negocio, solo empaqueta lo que ya vino del
// Modulo 02 (cierres_materializados).
const payload = {
  cierres_materializados: t.cierres_materializados || [],
  base_dir_dev: t.base_dir_dev,
  version_codigo: t.version_codigo || null,
};

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_motor_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_motor_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];
